#[test]fn native_local_not_sent_never_accepts_absence_or_unknown_phase(){let mut e=attempted();let mut v=event("live_package_no_execution",3002);v["evidence"]=json!({"kind":"local_queue_not_sent_v1","requestHash":"c".repeat(64),"sdkError":{"code":"AUTHORITY_REJECTED","status":null,"orderId":null,"apiCode":null,"mayHaveExecuted":false},"queueProof":{"tailRecord":{"state":{"unknown":{},"active":null,"manual_review":false}}}});deny(&mut e,&v);e.advance(&event("live_package_unknown",3002)).unwrap();deny(&mut e,&v);assert_eq!(e.report().unwrap()["reservedCash"],"4.500000");assert!(e.fills().is_empty());}

// Replay fixtures intentionally contain no account/client. Runtime tests must
// separately prove this evidence comes from the original locked dispatch log.
fn never_dispatch_fixture()->(Engine,Value){
 let mut e=engine();let mut r=reserve(2);let semantic=json!({"fixture":"native replay witness","wireLegs":r["legs"]});r["proofHash"]=json!(hash(&semantic));
 let scope=json!({"tournamentId":"cup","tournamentSlug":"cup","exchanges":{"101":"101","102":"102"}});
 let body=json!({"executionMode":"allOrNone","idempotencyKey":"run-package-1","legs":[{"exchangeId":"101","side":"yes","action":"buy","quantity":5,"price":0.45,"tournamentId":"cup"},{"exchangeId":"102","side":"yes","action":"buy","quantity":5,"price":0.45,"tournamentId":"cup"}]});
 let text=format!("{{\"method\":\"POST\",\"endpoint\":\"/orders/multi-leg\",\"body\":{body},\"bodyJson\":null}}");let spec:Value=serde_json::from_str(&text).unwrap();let request=format!("{:x}",Sha256::digest(text.as_bytes()));
 e.advance(&r).unwrap();let mut a=r.clone();a["type"]=json!("live_package_attempt");a["receivedAt"]=json!(iso(3001));a["processedAt"]=json!(iso(3001));a["requestHash"]=json!(request);a["idempotencyKey"]=json!("run-package-1");a["bookHashes"]=json!({"101":hash(&book("101")["book"]),"102":hash(&book("102")["book"])});e.advance(&a).unwrap();
 let admission=json!({"proof":semantic,"reserve":r,"spec":spec,"request_hash":request,"scope":scope,"permit":{"runId":"run-1","intentId":"package-1"},"basket":{"idempotencyKey":"run-package-1"},"queue_scope":"original-account","queue_binding":{"intent":"run-1:package-1","key":"run-package-1","payload_hash":hash(&json!({"scope":scope,"spec":spec}))}});
 let fence=json!({"kind":"never_attempted","packageId":"package-1","at":iso(3002),"requestHash":request,"admissionHash":hash(&admission),"priorHead":{"sequence":1,"hash":"d".repeat(64)}});
 let mut row=json!({"schemaVersion":1,"sequence":2,"previous":"d".repeat(64),"event":fence});row["hash"]=json!(hash(&row));
 let record=json!({"admission":admission,"phase":"never_attempted","attemptedAt":null,"outcome":fence});
 let mut v=r;v["type"]=json!("live_package_no_execution");v["receivedAt"]=json!(iso(3002));v["processedAt"]=json!(iso(3003));v["evidence"]=json!({"kind":"dispatch_never_attempted_v1","requestHash":request,"requestJson":text,"dispatchRecordHash":hash(&record),"dispatchRecord":record,"dispatchFenceRow":row,"dispatchHead":{"sequence":2,"hash":row["hash"],"poisoned":false},"journalBytes":1234,"journalSha256":"e".repeat(64),"journalLastClockMs":1_792_022_403_002i64});(e,v)
}
#[test]fn never_physical_dispatch_fence_releases_only_reservation_without_profit_or_fill(){let(mut e,v)=never_dispatch_fixture();let cash=e.report().unwrap()["cash"].clone();e.advance(&v).unwrap();assert_eq!(e.report().unwrap()["cash"],cash);assert_eq!(e.report().unwrap()["realized"],"0.000000");assert_eq!(e.report().unwrap()["reservedCash"],"0.000000");assert_eq!(e.package_records()[0]["phase"],"no_execution");assert!(e.live_order_bindings().is_empty()&&e.fills().is_empty());deny(&mut e,&v);}
#[test]fn never_dispatch_rejects_missing_changed_or_inconsistent_fence_source(){let(e,v)=never_dispatch_fixture();for case in ["phase","attempted","request","admission","fence","head","clock","source","extra"]{let mut bad=v.clone();match case{"phase"=>bad["evidence"]["dispatchRecord"]["phase"]=json!("intent"),"attempted"=>bad["evidence"]["dispatchRecord"]["attemptedAt"]=json!(iso(3001)),"request"=>bad["evidence"]["requestJson"]=json!("{}"),"admission"=>bad["evidence"]["dispatchRecord"]["admission"]["reserve"]["bankScope"]["runId"]=json!("another"),"fence"=>bad["evidence"]["dispatchFenceRow"]["event"]["kind"]=json!("attempt"),"head"=>bad["evidence"]["dispatchHead"]["sequence"]=json!(1),"clock"=>bad["evidence"]["journalLastClockMs"]=json!(1_792_022_403_004i64),"source"=>bad["evidence"]["journalSha256"]=Value::Null,_=>bad["evidence"]["queueAbsence"]=json!(true)}let mut candidate=e.clone();deny(&mut candidate,&bad);}}
#[test]fn never_dispatch_unknown_ack_and_partial_fill_never_release(){let(e,v)=never_dispatch_fixture();for case in ["unknown","ack","fill"]{let mut candidate=e.clone();if case=="unknown"{let mut u=v.clone();u["type"]=json!("live_package_unknown");u["requestHash"]=v["evidence"]["requestHash"].clone();u["receivedAt"]=json!(iso(3002));u["processedAt"]=json!(iso(3002));candidate.advance(&u).unwrap();}else{let q=candidate.order_records()[0].clone();candidate.advance(&actual("actual_order_ack",&q,3002)).unwrap();if case=="fill"{candidate.advance(&fill(&q,1,3002)).unwrap();}}let before=candidate.report().unwrap()["reservedCash"].clone();deny(&mut candidate,&v);assert_eq!(candidate.report().unwrap()["reservedCash"],before);}}
#[test]fn typed_dispatch_witness_is_not_a_reserved_or_absence_alias(){let(_,v)=never_dispatch_fixture();let r=v["evidence"]["dispatchRecord"]["admission"]["reserve"].clone();let mut e=engine();e.advance(&r).unwrap();deny(&mut e,&v);let(mut e,mut v)=never_dispatch_fixture();v["evidence"]=json!({"kind":"dispatch_never_attempted_v1","confirmedNetworkAttempts":0,"queueEmpty":true});deny(&mut e,&v);}
#[test]fn consistently_rehashed_unrelated_bank_or_queue_binding_is_still_not_native_authority(){
 let(e,v)=never_dispatch_fixture();for case in ["bank","queue","time"]{let mut bad=v.clone();let proof=&mut bad["evidence"];
  match case{"bank"=>proof["dispatchRecord"]["admission"]["reserve"]["bankScope"]["bankManifestHash"]=json!("f".repeat(64)),"queue"=>proof["dispatchRecord"]["admission"]["queue_binding"]["payload_hash"]=json!("f".repeat(64)),_=>proof["dispatchRecord"]["outcome"]["at"]=json!(iso(3000))}
  proof["dispatchRecord"]["outcome"]["admissionHash"]=json!(hash(&proof["dispatchRecord"]["admission"]));proof["dispatchFenceRow"]["event"]=proof["dispatchRecord"]["outcome"].clone();
  let mut body=proof["dispatchFenceRow"].clone();body.as_object_mut().unwrap().remove("hash");proof["dispatchFenceRow"]["hash"]=json!(hash(&body));proof["dispatchHead"]["hash"]=proof["dispatchFenceRow"]["hash"].clone();proof["dispatchRecordHash"]=json!(hash(&proof["dispatchRecord"]));
  let mut candidate=e.clone();deny(&mut candidate,&bad);
 }
}

#[test]fn thirty_second_intent_does_not_turn_ten_second_books_into_fresh_attempt_facts(){
 let mut e=engine();let mut r=reserve(2);r["expiresAt"]=json!(iso(30001));e.advance(&r).unwrap();assert_eq!(e.package_records()[0]["expiresAt"],1_792_022_430_001i64);
 let mut a=event("live_package_attempt",15000);deny(&mut e,&a);
 for ex in ["101","102"]{let mut b=book(ex);b["receivedAt"]=json!(iso(15000));for k in ["receivedAt","sourceAt","requestStartedAt"]{b["book"][k]=json!(iso(15000));}b["book"]["sequence"]=json!("2");a["bookHashes"][ex]=json!(hash(&b["book"]));e.advance(&b).unwrap();}
 e.advance(&a).unwrap();assert_eq!(e.package_records()[0]["phase"],"attempted");assert_eq!(e.package_records()[0]["expiresAt"],1_792_022_430_001i64);assert_eq!(e.report().unwrap()["reservedCash"],"4.500000");assert!(e.fills().is_empty());
}
#[test]fn thirty_second_expiry_does_not_relax_stale_reservation_books_or_source_clocks(){
 for case in ["all_old","source_old","request_old"]{let mut e=engine();let mut r=reserve(2);r["receivedAt"]=json!(iso(15000));r["processedAt"]=json!(iso(15000));r["expiresAt"]=json!(iso(45000));
  if case!="all_old"{for ex in ["101","102"]{let mut b=book(ex);b["receivedAt"]=json!(iso(15000));for k in ["receivedAt","sourceAt","requestStartedAt"]{b["book"][k]=json!(iso(15000));}b["book"][if case=="source_old"{"sourceAt"}else{"requestStartedAt"}]=json!(iso(0));b["book"]["sequence"]=json!("2");r["legs"][if ex=="101"{0}else{1}]["bookHash"]=json!(hash(&b["book"]));e.advance(&b).unwrap();}}
  deny(&mut e,&r);assert_eq!(e.report().unwrap()["reservedCash"],"0.000000");
 }
}
#[test]fn package_expiry_still_obeys_lifetime_entry_cutoff_and_original_attempt_deadline(){
 for case in ["lifetime","entry"]{let mut p=policy();p["lifetimeMs"]=json!(if case=="lifetime"{30000}else{200000});let mut e=engine_with(&p);let mut r=reserve(2);r["expiresAt"]=json!(if case=="lifetime"{iso(30002)}else{iso(100001)});deny(&mut e,&r);}
 let mut e=engine();let mut r=reserve(2);r["expiresAt"]=json!(iso(30001));e.advance(&r).unwrap();
 let mut a=event("live_package_attempt",30001);a["expiresAt"]=json!(iso(60000));deny(&mut e,&a);assert_eq!(e.package_records()[0]["phase"],"reserved");assert_eq!(e.package_records()[0]["expiresAt"],1_792_022_430_001i64);
}

// Synthetic replay fixture ONLY. Runtime tests obtain the opaque proof from the
// actual SDK; no JSON hash here is claimed to authenticate a local call.
fn first_call_fixture()->(Engine,Value){
 let(e,mut event)=never_dispatch_fixture();let mut record=event["evidence"]["dispatchRecord"].clone();let a=&record["admission"];
 let error=json!({"code":"WRITES_DISABLED","status":null,"mayHaveExecuted":false,"retryAfterMs":0,"orderId":null,"apiCode":null});
 let mut ticket=json!({"schemaVersion":1,"kind":"sdk_first_logical_invocation","accountScope":a["queue_scope"],"root":"/private/fixture","scope":a["scope"],"basket":a["basket"],"permit":a["permit"],"request":a["spec"],"requestSha256":a["request_hash"],"binding":a["queue_binding"],"createdAtMs":1_792_022_403_002i64,"invocationId":"fixture-first-call"});ticket["sha256"]=json!(hash(&ticket));
 let mut key=json!({"schemaVersion":1,"kind":"sdk_first_logical_key","accountScope":a["queue_scope"],"key":a["queue_binding"]["key"],"intent":a["queue_binding"]["intent"],"ticketSha256":ticket["sha256"]});key["sha256"]=json!(hash(&key));
 let mut terminal=json!({"schemaVersion":1,"kind":"sdk_before_first_admit_no_http","accountScope":a["queue_scope"],"binding":a["queue_binding"],"requestSha256":a["request_hash"],"ticketSha256":ticket["sha256"],"keyIndexSha256":key["sha256"],"invocationId":ticket["invocationId"],"startedAtMs":ticket["createdAtMs"],"completedAtMs":1_792_022_403_002i64,"stage":"before_first_admit_invocation","admitInvocations":0,"httpInvocations":0,"queueHealth":"not_established","originalError":error});terminal["sha256"]=json!(hash(&terminal));
 let original=json!({"kind":"sdk_before_first_admit_no_http","ticket":ticket,"keyIndex":key,"terminal":terminal});
 let outcome=json!({"kind":"first_call_not_sent","packageId":a["permit"]["intentId"],"at":iso(3003),"requestHash":a["request_hash"],"error":error,"firstCallEvidence":original});
 record["phase"]=json!("first_call_not_sent");record["attemptedAt"]=json!(iso(3001));record["outcome"]=outcome;
 event["receivedAt"]=json!(iso(3002));event["processedAt"]=json!(iso(3004));event["evidence"]=json!({"kind":"sdk_before_first_admit_no_http","requestHash":event["evidence"]["requestHash"],"requestJson":event["evidence"]["requestJson"],"sdkError":error,"dispatchRecordHash":hash(&record),"dispatchRecord":record,"dispatchHead":{"sequence":3,"hash":"f".repeat(64),"poisoned":false},"firstCallProof":original});(e,event)
}
#[test]fn original_first_call_proof_releases_only_funding_and_never_creates_cash_profit_or_fills(){let(mut e,event)=first_call_fixture();let before=e.report().unwrap();e.advance(&event).unwrap();let after=e.report().unwrap();for field in ["cash","realized","ownedCost"]{assert_eq!(after[field],before[field]);}assert_eq!(after["reservedCash"],"0.000000");assert_eq!(e.package_records()[0]["phase"],"no_execution");assert!(e.live_order_bindings().is_empty()&&e.fills().is_empty());deny(&mut e,&event);}
#[test]fn first_call_cannot_release_unknown_acknowledged_or_filled_package(){for phase in 0..3{let(mut e,event)=first_call_fixture();let mut unknown=event.clone();unknown["type"]=json!("live_package_unknown");unknown["receivedAt"]=json!(iso(3002));unknown["processedAt"]=json!(iso(3002));unknown["requestHash"]=e.package_records()[0]["requestHash"].clone();assert_eq!(e.package_records()[0]["phase"],"attempted");if phase==0{e.advance(&unknown).unwrap();assert_eq!(e.package_records()[0]["phase"],"unknown");}else{let quotes=e.order_records();for q in &quotes{e.advance(&actual("actual_order_ack",q,3002)).unwrap();}if phase==2{e.advance(&fill(&quotes[0],1,3003)).unwrap();}}let before=e.report().unwrap();deny(&mut e,&event);assert_eq!(e.report().unwrap(),before);}}
#[test]fn first_call_changed_or_incomplete_original_sources_never_release(){for case in 0..8{let(mut e,mut event)=first_call_fixture();match case{0=>event["evidence"]["firstCallProof"]["terminal"]["httpInvocations"]=json!(1),1=>event["evidence"]["dispatchRecord"]["phase"]=json!("attempt"),2=>event["evidence"]["sdkError"]["mayHaveExecuted"]=json!(true),3=>event["evidence"]["firstCallProof"]["ticket"]["binding"]["key"]=json!("other-key"),4=>event["evidence"]["dispatchHead"]["poisoned"]=json!(true),5=>event["evidence"]["firstCallProof"]["ticket"]["createdAtMs"]=json!(1_792_022_403_000i64),6=>event["evidence"]["dispatchRecord"]["outcome"]["error"]["code"]=json!("other-error"),_=>event["evidence"]["requestJson"]=json!("{}")};deny(&mut e,&event);assert_eq!(e.report().unwrap()["reservedCash"],"4.500000");assert!(e.fills().is_empty());}}

fn completed_package()->Engine{let mut e=attempted();let qs=e.order_records();for q in &qs{e.advance(&actual("actual_order_ack",q,3002)).unwrap();}for q in &qs{e.advance(&fill(q,5,3003)).unwrap();}for q in &qs{e.advance(&terminal(q,5,3004)).unwrap();}e.advance(&event("live_package_complete",3005)).unwrap();e}
fn portfolio_lease(mode:&str)->Value{json!({"version":1,"mode":mode,"bankHead":{"manifestHash":"b".repeat(64),"sequence":10,"previous":"a".repeat(64)},"holdings":[{"marketId":"101","exchangeId":"101","side":"YES","quantity":5},{"marketId":"102","exchangeId":"102","side":"YES","quantity":5}],"componentExchanges":["101","102","103"],"protectedPackageIds":["package-1"],"floorBefore":"5.000000","floorAfter":if mode=="whole_unwind"{"0.000000"}else{"8.000000"},"minimumCashProceeds":if mode=="whole_unwind"{"6.000000"}else{"0.000000"},"maximumPayoutBefore":"5.000000","minimumStatewiseDelta":if mode=="whole_unwind"{"1.000000"}else{"-2.250000"},"liquidationBenchmarkCash":"4.000000","classification":if mode=="whole_unwind"{"statewise_cash_unwind_edge"}else{"risk_hedge_locked_vs_liquidation"}})}
fn held_acquisition()->Value{let mut r=reserve(2);r["packageId"]=json!("held-package");r["receivedAt"]=json!(iso(5000));r["processedAt"]=r["receivedAt"].clone();r["expiresAt"]=json!(iso(14000));r["portfolio"]=portfolio_lease("marginal_acquisition");r["legs"]=json!([{"marketId":"103","exchangeId":"103","side":"YES","action":"buy","quantity":5,"limitPrice":"0.450000","bookHash":hash(&book("103")["book"])}]);r["economics"]=json!({"maximumCost":"2.250000","minimumPayout":"3.000000","minimumSurplus":"0.750000","feeTotal":"0.000000"});r}
fn unwind_fixture()->(Engine,Value){let mut e=completed_package();let mut legs=vec![];for ex in ["101","102"]{let mut b=book(ex);b["receivedAt"]=json!(iso(5000));for k in ["receivedAt","sourceAt","requestStartedAt"]{b["book"][k]=json!(iso(5000));}b["book"]["sequence"]=json!("2");b["book"]["bids"][0]["price"]=json!("0.600000");b["book"]["asks"][0]["price"]=json!("0.650000");e.advance(&b).unwrap();legs.push(json!({"marketId":ex,"exchangeId":ex,"side":"YES","action":"sell","quantity":5,"limitPrice":"0.600000","bookHash":hash(&b["book"])}));}let mut r=held_acquisition();r["packageId"]=json!("whole-unwind");r["portfolio"]=portfolio_lease("whole_unwind");r["legs"]=json!(legs);r["economics"]=json!({"maximumCost":"0.000000","minimumPayout":"1.000000","minimumSurplus":"1.000000","feeTotal":"0.000000"});(e,r)}
fn portfolio_attempt(r:&Value,e:&Engine,at:i64)->Value{let mut a=r.clone();a["type"]=json!("live_package_attempt");a["receivedAt"]=json!(iso(at));a["processedAt"]=a["receivedAt"].clone();a["requestHash"]=json!("c".repeat(64));a["idempotencyKey"]=json!(format!("run-{}",r["packageId"].as_str().unwrap()));let exs:std::collections::BTreeSet<_>=r["legs"].as_array().unwrap().iter().map(|l|l["exchangeId"].as_str().unwrap()).collect();a["bookHashes"]=e.live_package_books().iter().filter(|b|exs.contains(b["exchangeId"].as_str().unwrap())).map(|b|(b["exchangeId"].as_str().unwrap().to_owned(),json!(hash(b)))).collect::<serde_json::Map<_,_>>().into();a}
#[test]fn held_acquisition_leases_original_inventory_and_funds_new_order_exactly(){let mut e=completed_package();let old=e.wallet.quantity("101",moloch_replay::Side::Yes);e.advance(&held_acquisition()).unwrap();assert_eq!(e.wallet.quantity("101",moloch_replay::Side::Yes),old);assert_eq!(e.report().unwrap()["reservedCash"],"2.250000");assert_eq!(e.order_records().last().unwrap()["action"],"buy");let mut tick=json!({"type":"tick","receivedAt":iso(6000)});e.advance(&tick).unwrap();assert_eq!(e.report().unwrap()["reservedCash"],"2.250000");assert_eq!(e.order_records().last().unwrap()["retired"],false);tick["receivedAt"]=json!(iso(20000));e.advance(&tick).unwrap();assert_eq!(e.report().unwrap()["reservedCash"],"2.250000");}
#[test]fn held_lease_rejects_missing_quantity_wrong_parent_or_partial_graph(){for case in ["quantity","missing","parent","outside"]{let mut e=completed_package();let mut r=held_acquisition();match case{"quantity"=>r["portfolio"]["holdings"][0]["quantity"]=json!(4),"missing"=>r["portfolio"]["holdings"]=json!([]),"parent"=>r["portfolio"]["protectedPackageIds"]=json!([]),_=>r["portfolio"]["componentExchanges"]=json!(["102","103"])}deny(&mut e,&r);}}
#[test]fn whole_unwind_reserves_inventory_not_cash_and_only_actual_fills_release_protection(){let(mut e,r)=unwind_fixture();let cash=e.report().unwrap()["cash"].clone();e.advance(&r).unwrap();assert_eq!(e.report().unwrap()["reservedCash"],"0.000000");assert_eq!(e.report().unwrap()["cash"],cash);let attempt=portfolio_attempt(&r,&e,8000);e.advance(&attempt).unwrap();let qs:Vec<_>=e.order_records().into_iter().filter(|q|q["action"]=="sell").collect();for q in &qs{e.advance(&actual("actual_order_ack",q,8001)).unwrap();}let mut complete=attempt.clone();complete["type"]=json!("live_package_complete");deny(&mut e,&complete);for q in &qs{e.advance(&fill(q,5,8002)).unwrap();}for q in &qs{e.advance(&terminal(q,5,8003)).unwrap();}complete["receivedAt"]=json!(iso(8004));complete["processedAt"]=complete["receivedAt"].clone();e.advance(&complete).unwrap();assert_eq!(e.wallet.quantity("101",moloch_replay::Side::Yes),0);assert_eq!(e.wallet.quantity("102",moloch_replay::Side::Yes),0);let p=e.package_records();assert!(p.as_array().unwrap().iter().all(|p|p["protectionReleased"]==true));assert_eq!(e.report().unwrap()["cash"],"101.500000");}
#[test]fn whole_unwind_must_sell_every_held_component_and_cannot_use_floor_for_upside_profit(){for case in ["subset","quantity","statewise"]{let(mut e,mut r)=unwind_fixture();match case{"subset"=>{r["legs"].as_array_mut().unwrap().pop();},"quantity"=>r["legs"][0]["quantity"]=json!(4),_=>{r["portfolio"]["maximumPayoutBefore"]=json!("10.000000");r["portfolio"]["minimumStatewiseDelta"]=json!("-4.000000");}}deny(&mut e,&r);}}
#[test]fn unwind_unknown_preserves_parent_protection_and_owned_inventory(){let(mut e,r)=unwind_fixture();e.advance(&r).unwrap();let a=portfolio_attempt(&r,&e,8000);e.advance(&a).unwrap();let mut u=a.clone();u["type"]=json!("live_package_unknown");u["receivedAt"]=json!(iso(8001));u["processedAt"]=u["receivedAt"].clone();e.advance(&u).unwrap();assert_eq!(e.wallet.quantity("101",moloch_replay::Side::Yes),5);assert!(e.package_records().as_array().unwrap().iter().find(|p|p["packageId"]=="package-1").unwrap().get("protectionReleased").is_none());assert!(e.package_blocks_submissions());}
#[test]fn unwind_verified_zero_execution_keeps_original_package_protected(){let(mut e,r)=unwind_fixture();e.advance(&r).unwrap();let a=portfolio_attempt(&r,&e,8000);e.advance(&a).unwrap();let response=json!({"error":{"code":"RATE_LIMITED","message":"sanitized"}});let mut z=a;z["type"]=json!("live_package_no_execution");z["receivedAt"]=json!(iso(8001));z["processedAt"]=z["receivedAt"].clone();z["evidence"]=json!({"kind":"official_multi_leg_zero_execution","completeBody":true,"requestHash":"c".repeat(64),"receiptHash":"e".repeat(64),"responseHash":hash(&response),"response":response,"status":429,"requestStartedAt":iso(8000),"receivedAt":iso(8001)});e.advance(&z).unwrap();assert_eq!(e.wallet.quantity("101",moloch_replay::Side::Yes),5);assert_eq!(e.wallet.quantity("102",moloch_replay::Side::Yes),5);assert!(!e.package_blocks_submissions());assert!(e.package_records().as_array().unwrap().iter().find(|p|p["packageId"]=="package-1").unwrap().get("protectionReleased").is_none());}
#[test]fn wholly_covered_unwind_is_management_after_buy_entry_deadline(){let(mut e,r)=unwind_fixture();let mut p=policy();p["entryStopAt"]=json!(iso(4000));e.update_policy(&p).unwrap();e.advance(&r).unwrap();let attempt=portfolio_attempt(&r,&e,8000);e.advance(&attempt).unwrap();assert_eq!(e.package_records().as_array().unwrap().iter().find(|p|p["packageId"]=="whole-unwind").unwrap()["phase"],"attempted");}
#[test]fn buying_opposite_existing_side_is_not_a_synthetic_covered_hedge(){let mut e=completed_package();let mut r=held_acquisition();r["legs"][0]["marketId"]=json!("101");r["legs"][0]["exchangeId"]=json!("101");r["legs"][0]["side"]=json!("NO");r["legs"][0]["limitPrice"]=json!("0.600000");r["legs"][0]["bookHash"]=json!(hash(&book("101")["book"]));r["portfolio"]["floorAfter"]=json!("9.000000");r["economics"]=json!({"maximumCost":"3.000000","minimumPayout":"4.000000","minimumSurplus":"1.000000","feeTotal":"0.000000"});assert_eq!(e.advance(&r).unwrap_err(),"PACKAGE_HELD_BUY_CAP_OR_NETTING");}
